fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // tol is strictly positive as per problem statement
    let diff = (a as i16) - (b as i16);
    let tol_i16 = tol as i16;

    // Check if diff is in open interval (-tol, tol)
    diff > -tol_i16 && diff < tol_i16
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    assert_eq!(a.len(), b.len(), "Input vectors must have equal length");
    assert!(tol > 0, "Tolerance must be strictly positive");

    // Iterate over pairs of elements, map using is_close_i8, collect into a Vec<bool>
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}